//! Generated independently of the network envelope namespace.
use crate::bridge::*;
use ts_rs::{Config, TS};
pub fn typescript() -> String {
    let config = Config::default();
    let mut out = String::from(
        "// Generated by xtask generate-bridge. Do not edit.\nimport type { CharacterMotor, ControlEpoch, EntityId, InputFrame, VehicleMotor } from '@port-meridian/protocol';\nimport type { VehicleTemplate } from '@port-meridian/content';\n",
    );
    macro_rules! types { ($($t:ty),*) => { $(out.push_str("export "); out.push_str(&<$t>::decl(&config)); out.push_str("\n\n");)* }; }
    types!(
        PredictedFrame,
        VehiclePrediction,
        StepRequest,
        VehicleProxy,
        ProxySet,
        StaticRayQuery,
        StaticSphereQuery,
        StaticHit,
        StaticRayResult
    );
    out
}
